"use strict";
exports.makeSink = () => ({
  name: "island",
  seen: 0,
  take(n) {
    this.seen += n;
    return this.seen;
  },
});
exports.makeAdder = () => ({
  add(...ns) {
    return ns.reduce((a, b) => a + b, 100);
  },
});
exports.tableSize = (table) => table.size;
exports.makeStepper = () => {
  let n = 0;
  return {
    next(step) {
      n += step ?? 1;
      return { value: n, done: false };
    },
  };
};
